s://' : 'ws://';\n  const ws = new WebSocket(proto + location.host + '/ws?room=' + encodeURIComponent(mpRoom) + '&name=' + encodeURIComponent(mpName));\n  mpSocket = ws;\n  ws.onmessage = e => {\n    if (mpSocket !== ws) return;\n    let m; try { m = JSON.parse(e.data); } catch (_) { return; }\n    const p = m.id != null ? mpPeers.get(m.id) : null;\n    switch (m.t) {\n      case 'w':\n        mpId = m.id; mpClear();\n        for (const d of m.ps || []) mpMakePeer(d);\n        mpReady = true;\n        mpStatus('Terhubung · ' + (1 + (m.ps || []).length) + ' pilot · Room ' + mpRoom);\n        startGame(); toast('ONLINE · ROOM ' + mpRoom); mpBoard();\n        break;\n      case 'j': mpMakePeer(m); toast(String(m.n).toUpperCase() + ' BERGABUNG'); mpBoard(); break;\n      case 'l': if (p) { toast(p.name.toUpperCase() + ' KELUAR'); mpDropPeer(p); mpBoard(); } break;\n      case 's': if (p && !p.dead) mpSnap(p, m); break;\n      case 'f': if (p) { p.firing = !!m.w && !p.dead; if (p.firing && p.fireCd < 0) p.fireCd = 0; } break;\n      case 'hit': mpHitSelf(m.id, +m.d || 0); break;\n      case 'die': mpOnDie(m); break;\n      case 'r':\n        if (p) { p.dead = false; p.hp = 100; p.inv = MP_INV; p.buf.length = 0; p.ready = false; p.firing = false; mpBoard(); }\n        break;\n      case 'full': mpFull = true; mpStatus('Room penuh (maks. 8 pilot).'); break;\n    }\n  };\n  ws.onerror = () => mpStatus('Koneksi gagal. Periksa binding ROOMS.');\n  ws.onclose = () => {\n    if (mpSocket !== ws) return;\n    mpSocket = null; mpReady = false;\n    if (state !== 'menu') { toast('KONEKSI TERPUTUS'); toMenu(); }\n    mpStatus(mpFull ? 'Room penuh (maks. 8 pilot).' : 'Koneksi terputus.');\n  };\n}\nfunction mpTick(dt) {\n  if (!mpSocket || mpSocket.readyState !== 1 || !mpReady) return;\n  if (state !== 'play') { if (mpFiring) { mpFiring = false; mpSend({ t: 'f', w: 0 }); } return; }\n  mpSendT -= dt; if (mpSendT > 0) return;\n  mpSendT = 1 / 15;\n  mpSend({\n    t: 's',\n    p: [+S.pos.x.toFixed(2), +S.pos.y.toFixed(2), +S.pos.z.toFixed(2)],\n    r: [+S.pitch.toFixed(3), +S.yaw.toFixed(3), +S.roll.toFixed(3)],\n    v: +S.speed.toFixed(1), h: Math.round(S.hp)\n  });\n}\nsetTimeout(() => {\n  spawn = findSpawn();\n  S.pos.copy(spawn);\n  plane.position.copy(spawn);\n  updateChunks(spawn.x, spawn.z, true);\n  makeClouds(spawn.x, spawn.z);\n  orbitCam(0, spawn, true);\n  world(0);\n  composer.render();\n  state = 'menu';\n  showBest();\n  $('menu').classList.remove('hidden');\n  $('loader').classList.add('hidden');\n  requestAnimationFrame(t0 => { last = t0; requestAnimationFrame(frame); });\n}, 30);\n</script>\n</body>\n</html>\n";

const MANIFEST = "{\"name\": \"Origami Skies\", \"short_name\": \"Origami Skies\", \"start_url\": \"/\", \"display\": \"fullscreen\", \"orientation\": \"landscape\", \"background_color\": \"#0d1b24\", \"theme_color\": \"#0d1b24\"}";

const SinglePlayerApp = {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === '/manifest.webmanifest') {
      return new Response(MANIFEST, { headers: { 'content-type': 'application/manifest+json; charset=utf-8', 'cache-control': 'public, max-age=86400' } });
    }
    if (url.pathname === '/favicon.ico') return new Response(null, { status: 204 });
    if (url.pathname !== '/' && url.pathname !== '/index.html') return Response.redirect(new URL('/', url).toString(), 302);
    return new Response(HTML, {
      headers: {
        'content-type': 'text/html; charset=utf-8',
        'cache-control': 'public, max-age=300',
        'x-content-type-options': 'nosniff',
        'referrer-policy': 'strict-origin-when-cross-origin'
      }
    });
  }
};


// Multiplayer router + Durable Object room server
const MAX_ONLINE_PLAYERS = 8;
const cleanRoomCode = (value) => String(value || '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 8) || 'LOBBY';

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.pathname === '/ws') {
      if ((request.headers.get('Upgrade') || '').toLowerCase() !== 'websocket') return new Response('Expected WebSocket', { status: 426 });
      if (!env?.ROOMS) return new Response('ROOMS binding is not configured', { status: 501 });
      const roomName = cleanRoomCode(url.searchParams.get('room'));
      const room = env.ROOMS.get(env.ROOMS.idFromName(roomName));
      return room.fetch(request);
    }
    return SinglePlayerApp.fetch(request, env, ctx);
  }
};

// IMPORTANT: this named export must exactly match class_name = "Room" in wrangler.toml.
const RESPAWN_PROTECT_MS = 3000;   // spawn protection (also enforced on the client)
const MAX_HIT_DMG = 12;            // per-bullet damage cap
const MAX_HITS_PER_SEC = 14;       // per shooter (client fires ~9 bullets/s)

export class Room {
  constructor(state, env) { this.state = state; this.env = env; this.rl = new Map(); }

  async fetch(request) {
    if ((request.headers.get('Upgrade') || '').toLowerCase() !== 'websocket') return new Response('Expected WebSocket', { status: 426 });
    const current = this.state.getWebSockets();
    const pair = new WebSocketPair();
    const client = pair[0], server = pair[1];
    if (current.length >= MAX_ONLINE_PLAYERS) {
      this.state.acceptWebSocket(server);
      server.send(JSON.stringify({ t: 'full', max: MAX_ONLINE_PLAYERS }));
      server.close(1000, 'Room full');
      return new Response(null, { status: 101, webSocket: client });
    }
    const url = new URL(request.url);
    const players = current.map(ws => ws.deserializeAttachment()).filter(Boolean);
    let id; do { id = 1 + Math.floor(Math.random() * 2147483646); } while (players.some(p => p.id === id));
    const used = new Set(players.map(p => p.c)); let c = 0; while (used.has(c)) c++;
    const n = (url.searchParams.get('name') || 'Pilot').replace(/[<>&"]/g, '').trim().slice(0, 14) || 'Pilot';
    const envName = players.length ? players[0].env : (url.searchParams.get('env') === 'city' ? 'city' : 'nature');
    this.state.acceptWebSocket(server);
    // k = kills, d = deaths, x = currently dead, inv = spawn protection until (ms epoch)
    server.serializeAttachment({ id, n, c, k: 0, d: 0, x: false, inv: Date.now() + RESPAWN_PROTECT_MS, env: envName });
    server.send(JSON.stringify({ t: 'w', id, env: envName, ps: players.map(p => ({ id: p.id, n: p.n, c: p.c, k: p.k, d: p.d, x: !!p.x })) }));
    this.broadcast({ t: 'j', id, n, c, k: 0, d: 0, x: false }, server);
    return new Response(null, { status: 101, webSocket: client });
  }

  broadcast(obj, except) {
    const data = JSON.stringify(obj);
    for (const ws of this.state.getWebSockets()) if (ws !== except) { try { ws.send(data); } catch {} }
  }
  find(id) {
    for (const ws of this.state.getWebSockets()) { const p = ws.deserializeAttachment(); if (p?.id === id) return [ws, p]; }
    return [null, null];
  }

  webSocketMessage(ws, message) {
    if (typeof message !== 'string' || message.length > 800) return;
    let m; try { m = JSON.parse(message); } catch { return; }
    const p = ws.deserializeAttachment(); if (!p || !m || typeof m !== 'object') return;
    const num = v => Number.isFinite(+v) ? +v : 0;
    const now = Date.now();

    switch (m.t) {
      case 's': // position snapshot (dead players do not send/relay)
        if (p.x || !Array.isArray(m.p) || !Array.isArray(m.r)) return;
        this.broadcast({ t: 's', id: p.id, p: m.p.slice(0, 3).map(num), r: m.r.slice(0, 3).map(num), v: num(m.v), h: Math.max(0, Math.min(100, num(m.h))) }, ws);
        break;

      case 'f': // trigger on/off (peers simulate the tracer cadence locally)
        this.broadcast({ t: 'f', id: p.id, w: p.x ? 0 : Math.max(0, Math.min(2, m.w | 0)) }, ws);
        break;

      case 'hit': { // shooter -> victim damage, validated + rate limited
        if (p.x || typeof m.to !== 'number' || m.to === p.id) return;
        const b = this.rl.get(p.id) || { t: now, n: 0 };
        if (now - b.t > 1000) { b.t = now; b.n = 0; }
        if (++b.n > MAX_HITS_PER_SEC) { this.rl.set(p.id, b); return; }
        this.rl.set(p.id, b);
        const [tw, tp] = this.find(m.to);
        if (!tw || tp.x || tp.inv > now) return;
        try { tw.send(JSON.stringify({ t: 'hit', id: p.id, d: Math.max(0, Math.min(MAX_HIT_DMG, num(m.d))) })); } catch {}
        break;
      }

      case 'die': { // victim reports death; server owns the K/D counters
        if (p.x) return; // ignore duplicates
        p.x = true; p.d++; p.inv = 0;
        ws.serializeAttachment(p);
        let by = null, k = 0;
        if (typeof m.by === 'number' && m.by !== p.id) {
          const [kw, kp] = this.find(m.by);
          if (kw && kp) { kp.k++; k = kp.k; by = kp.id; kw.serializeAttachment(kp); }
        }
        this.broadcast({ t: 'die', id: p.id, by, k, d: p.d }); // includes the victim itself
        break;
      }

      case 'r': // respawn
        if (!p.x) return;
        p.x = false; p.inv = now + RESPAWN_PROTECT_MS;
        ws.serializeAttachment(p);
        this.broadcast({ t: 'r', id: p.id });
        break;
    }
  }

  webSocketClose(ws) {
    const p = ws.deserializeAttachment();
    if (p) { this.rl.delete(p.id); this.broadcast({ t: 'l', id: p.id }, ws); }
  }
  webSocketError(ws) { this.webSocketClose(ws); }
}